#include "study_support.h"
extern "C" int study_check(const char*path,double*met){try{std::ifstream f(path,std::ios::binary);std::vector<float>v(outcount());f.read((char*)v.data(),v.size()*4);if(!f||f.peek()!=EOF)throw std::runtime_error("artifactsize");size_t pos=0;auto exact=[&](float x){float y=v.at(pos++);if(memcmp(&x,&y,4))throw std::runtime_error("full_input_output_tmp_guard_mismatch");};exact(6);for(int n:sizes()){exact(n);for(int r=0;r<2;r++)for(float x:fixture(n,r))exact(x);}for(int n:sizes()){for(int r=0;r<2;r++)for(int i=0;i<n;i++)exact(1.5f+float(i%17-8)/16.f);int half=(n+1)/2,tail=n-half;for(int r=0;r<2;r++){auto x=fixture(n,1-r);int start=r==0?half:0,len=r==0?tail:half;for(int i=0;i<half;i++)exact(i<len?x[start+i]:-777.f);}for(int r=0;r<2;r++)for(int i=0;i<384;i++)exact(-777.f);}if(pos!=v.size())throw std::runtime_error("count");met[0]=0;met[1]=0;return 0;}catch(std::exception&e){fprintf(stderr,"ALLREDUCE_CHECK_FAIL %s\n",e.what());return 1;}}
